import {formatHyper,HYPER_HELP} from './hyper.js';
export function paintHyper(hyper,features=null){const put=(id,text)=>{const e=document.getElementById(id);if(e)e.textContent=text;};put('hyper-value',formatHyper(hyper.power));put('hyper-name',hyper.milestone.name);put('hyper-fuel','⚡ '+hyper.fuel);put('hyper-tap-gain','+'+hyper.chargePerAction+' FUEL');const value=document.getElementById('hyper-value');if(value)value.title=HYPER_HELP;for(const id of ['advance','amplifier']){const offer=hyper.offer(id),button=document.getElementById('hyper-buy-'+id);if(button)button.disabled=!offer.canBuy||features&&(!features.hyper||id==='advance'&&hyper.rank>=features.maxHyperRank);put('hyper-label-'+id,offer.name);put('hyper-cost-'+id,'⚡ '+offer.cost);put('hyper-effect-'+id,features&&id==='advance'&&hyper.rank>=features.maxHyperRank?'転生ツリーで到達上限を研究':offer.effect);if(id==='advance')put('hyper-next','NEXT '+formatHyper(offer.nextPower));}}
